/**
 * 从错误对象中提炼用户可读的提示文案（对标 React 版 client.ts extractErrorMessage）。
 * 优先后端错误体；保留拒绝时给出简洁友好的一句。
 */
import { HttpErrorResponse } from '@angular/common/http';

import type { ApiError } from '../../models/common.model';
import { ErrorCode } from '../../models/common.model';

/** 非业务异常的 HTTP 状态默认文案。 */
const STATUS_TEXT: Record<number, string> = {
  400: '请求参数有误。',
  401: '未授权或登录已过期。',
  403: '没有权限执行该操作。',
  404: '资源不存在。',
  409: '资源冲突，请检查后重试。',
  413: '文件过大。',
  429: '操作过于频繁，请稍后再试。',
};

export function extractErrorMessage(error: unknown, fallback = '操作失败。'): string {
  if (error instanceof HttpErrorResponse) {
    const data = error.error as ApiError | null;
    // 保留拒绝：简洁友好，而不是冗长的后端文案。
    if (data?.code === ErrorCode.FileUnderRetention || data?.code === ErrorCode.FileUnderLegalHold) {
      return data.code === ErrorCode.FileUnderLegalHold
        ? '该文件已被法定保留，禁止删除/覆盖。'
        : '该文件已被保留，禁止删除/覆盖。';
    }
    if (typeof data?.message === 'string' && data.message) {
      return data.message;
    }
    const status = error.status;
    if (status && STATUS_TEXT[status]) {
      return STATUS_TEXT[status];
    }
  }
  if (error instanceof Error && error.message) {
    return error.message;
  }
  return fallback || '操作失败。';
}
