import { HttpErrorResponse } from '@angular/common/http';

import { extractErrorMessage } from './error.util';
import { ErrorCode } from '../../models/common.model';

describe('extractErrorMessage', () => {
  it('HttpErrorResponse 401 使用状态默认文案', () => {
    const err = new HttpErrorResponse({ status: 401, statusText: 'Unauthorized' });
    expect(extractErrorMessage(err)).toBe('未授权或登录已过期。');
  });

  it('HttpErrorResponse 404 使用状态默认文案', () => {
    const err = new HttpErrorResponse({ status: 404 });
    expect(extractErrorMessage(err)).toBe('资源不存在。');
  });

  it('优先取后端业务 message', () => {
    const err = new HttpErrorResponse({
      status: 400,
      error: { code: 'ValidationFailed', message: '文件名不能为空。' },
    });
    expect(extractErrorMessage(err)).toBe('文件名不能为空。');
  });

  it('保留拒绝（FileUnderRetention / FileUnderLegalHold）给专用文案', () => {
    const r = new HttpErrorResponse({
      status: 409,
      error: { code: ErrorCode.FileUnderRetention, message: 'raw' },
    });
    expect(extractErrorMessage(r)).toBe('该文件已被保留，禁止删除/覆盖。');

    const l = new HttpErrorResponse({
      status: 409,
      error: { code: ErrorCode.FileUnderLegalHold, message: 'raw' },
    });
    expect(extractErrorMessage(l)).toBe('该文件已被法定保留，禁止删除/覆盖。');
  });

  it('Error 实例取 message', () => {
    expect(extractErrorMessage(new Error('磁盘已满。'))).toBe('磁盘已满。');
  });

  it('未知类型回退默认文案', () => {
    expect(extractErrorMessage('some string')).toBe('操作失败。');
    expect(extractErrorMessage(null)).toBe('操作失败。');
    expect(extractErrorMessage(undefined)).toBe('操作失败。');
    expect(extractErrorMessage('x', '自定义兜底。')).toBe('自定义兜底。');
  });

  it('后端 message 为空时按状态兜底', () => {
    const err = new HttpErrorResponse({ status: 429, error: { code: 'X', message: '' } });
    expect(extractErrorMessage(err)).toBe('操作过于频繁，请稍后再试。');
  });
});
