/**
 * 通用基础类型.
 * 来源：React 版 src/api/types/Common.d.ts、ErrorTypes.ts（后端为真相源）。
 */

/** 存储类（StorageClass.cs）. */
export type StorageClass = 'Standard' | 'InfrequentAccess' | 'Archive';

/**
 * 内容加密模式（镜像后端 Contracts/Enums/EncryptionMode.cs）.
 * - ServerSide：服务端加密（SSE），服务端可读明文并执行内容治理（默认）。
 * - EndToEnd：端到端加密（零知识），客户端加密直传，服务端仅存密文。
 */
export type EncryptionMode = 'ServerSide' | 'EndToEnd';

/** 后端统一错误响应体：成功返回裸数据；失败返回 { code, message }. */
export interface ApiError {
  code: number;
  message: string;
}

/** 后端 ErrorCode 枚举（与 Contracts/ErrorCodes.cs 对齐）. */
export enum ErrorCode {
  None = 0,
  UnspecifiedError = 10000,

  BadRequest = 40000,
  ValidationFailed = 40001,
  InvalidParentFolder = 40002,
  FileTooLarge = 40003,
  DuplicateFileKey = 40004,
  UploadPartInvalid = 40005,

  Unauthorized = 40100,
  TokenExpired = 40101,
  InvalidToken = 40102,

  Forbidden = 40300,
  PermissionDenied = 40301,
  SharePasswordIncorrect = 40302,
  FileUnderRetention = 40303,
  FileUnderLegalHold = 40304,

  NotFound = 40400,
  BucketNotFound = 40401,
  FileNotFound = 40402,
  ShareNotFound = 40403,
  UploadSessionNotFound = 40404,
  RecycleBinItemNotFound = 40405,
  FileVersionNotFound = 40406,

  Conflict = 40900,
  ShareRevoked = 40901,

  Gone = 41000,
  ShareExpired = 41001,
  ShareMaxDownloadsExceeded = 41002,
  UploadSessionExpired = 41003,

  PayloadTooLarge = 41300,
  QuotaExceeded = 41301,
  TooManyRequests = 42900,

  InternalServerError = 50000,
  StorageServerError = 50001,
  ServiceUnavailable = 50300,
  StorageUnavailable = 50301,
}
